import React, { useState, useEffect, useCallback } from 'react';
import { List, Card, Typography, Tag, Empty, Button, Modal, Form, Input, message, Badge, Tabs, Popconfirm } from 'antd';
import { DeleteOutlined } from '@ant-design/icons';
import { useAuth } from '../../AuthContext';
import api from '../../api';
import './FeedbackPage.css';

const { Text } = Typography;
const { TextArea } = Input;

function FeedbackPage() {
  const [activeTab, setActiveTab] = useState('inbox');
  const [conversations, setConversations] = useState([]);
  const [selectedConversation, setSelectedConversation] = useState(null);
  const [replyModal, setReplyModal] = useState({ open: false, message: null });
  const [replyingTo, setReplyingTo] = useState(null);
  const [replyForm] = Form.useForm();
  const { user } = useAuth();

  const fetchConversations = useCallback(async () => {
    try {
      const res = await api.getFeedback();
      // Группировка по тредам с поиском корневого сообщения
      const grouped = res.data.reduce((acc, msg) => {
        if (!msg.parent_id) {
          // Это оригинальное сообщение
          acc[msg.id] = {
            id: msg.id,
            original: msg,
            replies: [],
            unread: msg.is_read === 0,
            lastMessage: msg,
            student: { name: msg.from_name, login: msg.from_login, id: msg.from_user_id }
          };
        } else {
          // Это ответ - ищем корневое сообщение
          let rootId = msg.parent_id;
          let depth = 0;
          while (depth < 10) {
            const parent = res.data.find(m => m.id === rootId);
            if (!parent || !parent.parent_id) break;
            rootId = parent.parent_id;
            depth++;
          }
          
          if (acc[rootId]) {
            acc[rootId].replies.push(msg);
            acc[rootId].lastMessage = msg;
            // Если ответ не прочитан и это не наш ответ (ментора), помечаем как непрочитанный
            if (msg.is_read === 0 && msg.from_user_id !== user?.id) {
              acc[rootId].unread = true;
            }
          }
        }
        return acc;
      }, {});
      
      const sorted = Object.values(grouped).sort((a, b) => 
        new Date(b.lastMessage.created_at) - new Date(a.lastMessage.created_at)
      );
      setConversations(sorted);
      return sorted;
    } catch {
      return [];
    }
  }, [user?.id]);

  useEffect(() => {
    fetchConversations();
  }, []);

  const markAsRead = async (messageId) => {
    try {
      await api.markFeedbackRead(messageId);
      setConversations(prev => prev.map(conv => 
        conv.id === messageId ? { ...conv, unread: false } : conv
      ));
    } catch (error) {
      console.error('Ошибка при отметке прочитанным:', error);
      // Не показываем ошибку пользователю, так как это фоновая операция
    }
  };

  const handleReply = async (values) => {
    try {
      console.log('Отправка ответа:', values);
      
      await api.replyFeedback({
        to_id: values.to_id,
        to_name: values.to_name,
        to_login: values.to_login,
        original_feedback_id: values.original_feedback_id,
        subject: `Re: ${values.subject || 'Без темы'}`,
        message: values.message
      });
      message.success('Ответ отправлен!');
      setReplyModal({ open: false, message: null });
      setReplyingTo(null);
      replyForm.resetFields();
      
      // Перезагружаем переписки и находим обновлённую
      setTimeout(async () => {
        const originalId = values.original_feedback_id;
        const updatedConvs = await fetchConversations();
        const updatedConv = updatedConvs.find(c => c.original?.id === originalId);
        if (updatedConv) {
          setSelectedConversation(updatedConv);
          setActiveTab('conversation');
        }
      }, 500);
    } catch (error) {
      console.error('Ошибка отправки ответа:', error);
      const errorMsg = error.response?.data?.error || error.message || 'Ошибка отправки ответа';
      message.error(errorMsg);
    }
  };

  const handleConversationClick = (conv) => {
    if (conv.unread && conv.original) {
      markAsRead(conv.original.id);
    }
    setSelectedConversation(conv);
    setActiveTab('conversation');
  };

  const handleDeleteConversation = async (studentId, studentName) => {
    try {
      await api.deleteConversation(studentId);
      message.success(`Переписка с ${studentName} удалена`);
      // Сбрасываем текущую переписку если удалили её
      if (selectedConversation?.student?.id === studentId) {
        setSelectedConversation(null);
        setActiveTab('inbox');
      }
      // Обновляем список
      fetchConversations();
    } catch (error) {
      console.error('Ошибка удаления переписки:', error);
      message.error('Ошибка при удалении переписки');
    }
  };

  // Обновляем форму при изменении selectedConversation
  useEffect(() => {
    if (selectedConversation) {
      replyForm.setFieldsValue({
        to_id: selectedConversation.student?.id,
        to_name: selectedConversation.student?.name,
        to_login: selectedConversation.student?.login,
        original_feedback_id: selectedConversation.original?.id,
        subject: selectedConversation.original?.subject
      });
    }
  }, [selectedConversation, replyForm]);

  const handleCardClick = (item) => {
    if (item.is_read === 0) {
      markAsRead(item.id);
    }
    setReplyingTo(item);
    setReplyModal({ open: true, message: item });
  };

  const formatDate = (dateStr) => {
    return new Date(dateStr).toLocaleString('ru-RU', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const inboxTab = (
    <List
      dataSource={conversations}
      locale={{ emptyText: <Empty description="Нет сообщений" /> }}
      renderItem={(conv) => (
        <List.Item>
          <Card 
            onClick={() => handleConversationClick(conv)}
            style={{ 
              width: '100%', 
              cursor: 'pointer',
              borderLeft: conv.unread ? '4px solid #1890ff' : '4px solid transparent'
            }}
            hoverable
            className={conv.unread ? 'feedback-card-unread' : ''}
            actions={[
              <Popconfirm
                key="delete"
                title={`Удалить переписку с ${conv.student.name}?`}
                description="Все сообщения будут удалены безвозвратно"
                onConfirm={(e) => {
                  e?.stopPropagation();
                  handleDeleteConversation(conv.student.id, conv.student.name);
                }}
                onCancel={(e) => e?.stopPropagation()}
                okText="Удалить"
                cancelText="Отмена"
                okButtonProps={{ danger: true }}
              >
                <Button 
                  type="text" 
                  danger 
                  icon={<DeleteOutlined />}
                  onClick={(e) => e.stopPropagation()}
                >
                  Удалить
                </Button>
              </Popconfirm>
            ]}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
              <div>
                <Text strong style={{ fontSize: 15 }}>
                  {conv.student.name} {conv.unread && <span style={{ color: '#1890ff', marginLeft: 8 }}>●</span>}
                </Text>
                <div style={{ fontSize: 13, color: '#666', marginTop: 4 }}>
                  {conv.original?.subject || 'Без темы'}
                </div>
              </div>
              <Text type="secondary" style={{ fontSize: 12 }}>{formatDate(conv.lastMessage.created_at)}</Text>
            </div>
            <div style={{ color: '#666', marginTop: 8, fontSize: 14 }}>
              {conv.lastMessage.message?.substring(0, 100)}{conv.lastMessage.message?.length > 100 ? '...' : ''}
            </div>
            {conv.replies.length > 0 && (
              <Tag color="blue" style={{ marginTop: 8 }}>
                Переписка ({conv.replies.length})
              </Tag>
            )}
          </Card>
        </List.Item>
      )}
    />
  );

  const conversationTab = selectedConversation ? (
    <div className="conversation-view">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
        <Button onClick={() => setActiveTab('inbox')}>
          ← Назад к списку
        </Button>
        <Popconfirm
          title={`Удалить переписку с ${selectedConversation.student.name}?`}
          description="Все сообщения будут удалены безвозвратно"
          onConfirm={() => handleDeleteConversation(selectedConversation.student.id, selectedConversation.student.name)}
          okText="Удалить"
          cancelText="Отмена"
          okButtonProps={{ danger: true }}
        >
          <Button danger icon={<DeleteOutlined />}>
            Удалить переписку
          </Button>
        </Popconfirm>
      </div>
      
      <Card style={{ marginBottom: 16 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 12 }}>
          <Text strong style={{ fontSize: 16 }}>
            {selectedConversation.student.name} ({selectedConversation.student.login})
          </Text>
          <Text type="secondary">{formatDate(selectedConversation.original?.created_at)}</Text>
        </div>
        {selectedConversation.original?.subject && (
          <div style={{ marginBottom: 8 }}>
            <Text strong>Тема: </Text>
            <Text>{selectedConversation.original.subject}</Text>
          </div>
        )}
        <div style={{ padding: 12, background: '#f5f5f5', borderRadius: 6, marginBottom: 12 }}>
          {selectedConversation.original?.message}
        </div>
        {selectedConversation.replies.map((reply, idx) => (
          <div key={reply.id} style={{ 
            padding: 12, 
            background: idx % 2 === 0 ? '#e6f7ff' : '#f6ffed',
            borderRadius: 6,
            marginBottom: 8,
            marginLeft: idx % 2 === 0 ? 0 : 40
          }}>
            <Text type="secondary" style={{ fontSize: 12, display: 'block', marginBottom: 4 }}>
              {formatDate(reply.created_at)}
            </Text>
            {reply.message}
          </div>
        ))}
      </Card>

      <Card>
        <Form form={replyForm} onFinish={handleReply} layout="vertical">
          {/* Скрытые поля с данными студента */}
          <Form.Item name="to_id" style={{ display: 'none' }}>
            <Input />
          </Form.Item>
          <Form.Item name="to_name" style={{ display: 'none' }}>
            <Input />
          </Form.Item>
          <Form.Item name="to_login" style={{ display: 'none' }}>
            <Input />
          </Form.Item>
          <Form.Item name="original_feedback_id" style={{ display: 'none' }}>
            <Input />
          </Form.Item>
          
          <Form.Item
            label="Ваш ответ"
            name="message"
            rules={[{ required: true, message: 'Введите ответ' }]}
          >
            <TextArea
              rows={4}
              placeholder="Напишите ответ..."
              style={{ resize: 'vertical' }}
            />
          </Form.Item>
          <Form.Item>
            <Button type="primary" htmlType="submit" block size="large">
              Отправить ответ
            </Button>
          </Form.Item>
        </Form>
      </Card>
    </div>
  ) : (
    <Empty description="Выберите переписку" />
  );

  const tabItems = [
    {
      key: 'inbox',
      label: `Входящие (${conversations.filter(c => c.unread).length})`,
      children: inboxTab
    },
    {
      key: 'conversation',
      label: 'Переписка',
      children: conversationTab,
      disabled: !selectedConversation
    }
  ];

  return (
    <div className="feedback-page">
      <h2>Обратная связь</h2>
      <Tabs activeKey={activeTab} items={tabItems} onChange={setActiveTab} />
    </div>
  );
}

export default FeedbackPage;
